import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1178, own='cte_101.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 758 Forensic Science / Criminal Investigation ----
H("758.d.1.A",3,"A student studies how detectives gather facts, interview people and build a case for prosecutors. This analyzes the field of:","criminal investigations",["tax preparation","urban planning","interior design"],"Investigation seeks facts to identify offenders.")
H("758.d.1.A",4,"The main purpose of a criminal investigation is to:","gather facts to determine what happened and who is responsible",["punish suspects before trial","entertain the public","avoid evidence"],"Investigations collect facts.")
H("758.d.1.B",3,"Two detectives are compared: one is patient, detail-oriented and objective, the other jumps to conclusions. This compares characteristics of:","an effective investigator",["a good salesperson","a skilled pilot","a talented chef"],"Effective investigators are objective and thorough.")
H("758.d.1.B",4,"Which trait most helps an investigator build a reliable case?","objectivity and attention to detail",["bias and haste","carelessness","guessing"],"Objectivity avoids tunnel vision.")
H("758.d.1.C",3,"The first officer arrives, aids the injured, secures the scene and notes who was present. This examines the:","preliminary investigation",["final trial","sentencing","parole review"],"Initial response begins the case.")
H("758.d.1.C",4,"One of the first duties of the officer arriving at a crime scene is to:","protect life and secure the scene",["collect souvenirs","leave quickly","clean up"],"Safety and preservation come first.")
H("758.d.1.D",3,"After the scene is processed, detectives re-interview witnesses, canvass the area and check records. This researches:","follow-up procedures for an investigation",["vacation planning","school scheduling","menu planning"],"Follow-up develops new leads.")
H("758.d.1.D",4,"A follow-up investigation often includes:","re-interviewing witnesses and reviewing lab results",["ending all work","ignoring leads","destroying notes"],"It builds on preliminary findings.")
H("758.d.1.E",3,"A detective tracks how cooperation among patrol officers, lab analysts and prosecutors affected a case. This evaluates:","interrelationships among individuals involved in an investigation",["rivalries in sports","weather patterns","road conditions"],"Teamwork affects outcomes.")
H("758.d.1.E",4,"Strong working relationships with prosecutors help investigators by:","improving case preparation and communication",["hiding evidence","slowing cases","reducing accuracy"],"Coordination strengthens cases.")
H("758.d.2.A",3,"An investigator writes down times, names and observations at the scene so details are not forgotten. This explains the use of:","field notes",["billboards","playlists","menus"],"Notes preserve facts.")
H("758.d.2.A",4,"Field notes are valuable because they:","preserve accurate details for reports and court",["replace evidence","entertain jurors","avoid documentation"],"Notes support testimony.")
H("758.d.2.B",3,"A trainee records the date, location, weather and who was present before describing each item. This demonstrates when, what, where and how to take:","investigative notes",["recipes","lecture slides","travel plans"],"Note content follows a pattern.")
H("758.d.2.B",4,"Which information belongs in field notes?","time, location and observed facts",["personal opinions only","guesses about guilt","jokes"],"Record facts, not conclusions.")
H("758.d.2.C",3,"The investigator writes legibly in ink, avoids erasing and corrects mistakes with a single line. This shows how to:","effectively take notes during an investigation",["hide mistakes","destroy notes","use pencil only"],"Notes must be clear and reliable.")
H("758.d.2.C",4,"If an error is made in field notes, the investigator should:","draw a single line through it and initial the change",["erase it","tear out the page","use correction fluid"],"Original text stays visible.")
H("758.d.2.D",3,"A team debates whether photographs show scene detail well but may miss smell, sound or scale. This distinguishes advantages and disadvantages of:","photographs and videos in an investigation",["written wills","signed notes","spoken reports"],"Photos capture detail but have limits.")
H("758.d.2.D",4,"A disadvantage of relying only on photographs is that they:","may not show scale, depth or everything present",["are always inadmissible","cost nothing","cannot be stored"],"Photos have limits.")
H("758.d.2.E",3,"Before shooting, an investigator plans overall, mid-range and close-up shots with a scale in each close-up. This plans use of:","digital investigative photography",["fashion photography","portrait photography","sports photography"],"Plan to document systematically.")
H("758.d.2.E",4,"A scale is placed beside an item in a close-up photo to:","show the true size of the item",["hide the item","add color","block the view"],"Scale enables measurement.")
H("758.d.2.F",3,"A photographer takes wide, medium and close-up pictures of a scene in a logical order and logs each frame. This organizes:","a photographic sequence of a crime scene",["a travel album","a school yearbook","a wedding album"],"Sequences tell the scene's story.")
H("758.d.2.F",4,"A common photographic sequence at a scene moves from:","overall views to mid-range to close-ups",["close-ups only","random shots","one angle only"],"Overall to detail.")
H("758.d.2.G",3,"A student studies a series of scene photos, infers what happened and predicts what else may be found. This is the skill of:","analyzing and evaluating photographs to make inferences",["ignoring images","guessing wildly","avoiding detail"],"Photos can support reasoning.")
H("758.d.2.G",4,"An inference from a crime scene photo should be based on:","visible evidence and logical reasoning",["rumors","hunches alone","a coin toss"],"Inferences need support.")
H("758.d.2.H",3,"An attorney asks whether photos are fair, accurate and relevant before showing them to a jury. This relates to:","admissibility of photographs in court",["film reviews","art contests","prize rules"],"Photos must be authenticated.")
H("758.d.2.H",4,"For a photograph to be admitted as evidence, a witness generally must testify that it:","fairly and accurately depicts the scene",["was edited for clarity","was taken years later","is artistic"],"Foundation is required.")
H("758.d.3.A",3,"Before drawing, a trainee walks the scene, notes the layout and decides on a plan for the sketch. This reflects:","planning and observation prior to sketching a crime scene",["skipping steps","drawing at random","ignoring the scene"],"Observation precedes the sketch.")
H("758.d.3.A",4,"Before sketching a scene, the investigator should first:","observe and plan the layout",["erase evidence","leave the scene","print photos"],"Plan first.")
H("758.d.3.B",3,"A sketch shows a compass direction, a scale, a legend and measured distances to key items. These are:","elements of a crime scene sketch",["parts of a menu","parts of a ticket","parts of a poster"],"Sketches include measurements and keys.")
H("758.d.3.B",4,"A legend on a crime scene sketch explains:","the symbols and items shown",["the artist's name only","the weather","the weekly schedule"],"Legends decode symbols.")
H("758.d.3.C",3,"A trainee measures an item's distance from two fixed walls to place it on the drawing. This develops a sketch using:","coordinates or measurements from fixed points",["guesses","colors","music"],"Fixed points anchor evidence.")
H("758.d.3.C",4,"Measurements for a scene sketch are best taken from:","fixed, permanent reference points",["movable furniture","other evidence","changing objects"],"Fixed points do not move.")
H("758.d.3.D",3,"An investigator writes a narrative of the room's layout, evidence positions and conditions as the sketch is made. This summarizes the scene by:","taking notes and recording details",["ignoring details","copying a movie","waiting a week"],"Notes complement sketches.")
H("758.d.3.D",4,"Notes taken with a sketch should describe:","conditions, items and observed details",["guesses about motive","unrelated chatter","personal feelings"],"Record facts.")
H("758.d.3.E",3,"A supervisor reviews the rough sketch for missing measurements and mislabeled items. This evaluates:","the accuracy and completeness of a crime scene sketch",["the artist's fame","the paper quality","the room's decor"],"Review catches errors.")
H("758.d.3.E",4,"Reviewing a rough sketch helps ensure that it is:","accurate and complete",["colorful","humorous","oversized"],"Quality control.")
H("758.d.3.F",3,"A rough sketch is later redrawn neatly to scale using drafting tools. This describes the:","final sketch or finished scale drawing",["first draft only","verbal report","phone note"],"Final drawings are scaled and neat.")
H("758.d.3.F",4,"A finished scale drawing differs from a rough sketch because it is:","neat and drawn to scale",["messy","unlabeled","hand-waved"],"Final drawings are polished.")
H("758.d.4.A",3,"A report writer sorts facts, arranges them in order and chooses clear wording. This distinguishes organizing information, structuring the narrative and:","writing the report in clear language",["hiding results","omitting facts","guessing"],"Good reports are organized and clear.")
H("758.d.4.A",4,"A well-structured investigative narrative should be:","chronological, clear and factual",["scrambled","vague","opinion-based"],"Order and clarity matter.")
H("758.d.4.B",3,"A prosecutor, a supervisor and a defense attorney may all rely on an officer's written account. This shows the importance and uses of:","investigative reports",["recipes","brochures","maps"],"Reports support decisions and testimony.")
H("758.d.4.B",4,"Investigative reports are used to:","document facts for prosecution, supervision and court",["decorate offices","replace evidence","hide facts"],"Reports are official records.")
H("758.d.4.C",3,"A review finds reports that skip details, include opinions or contain misspellings. This analyzes:","common problems with investigative reports",["common recipes","common melodies","common routes"],"Reports can be incomplete or biased.")
H("758.d.4.C",4,"A common problem in weak investigative reports is:","missing or unclear details",["too much accuracy","perfect order","complete facts"],"Gaps weaken reports.")
H("758.d.4.D",3,"An officer dictates observations into a recorder at the scene for later transcription. This researches ways to:","record and dictate for future report writing",["avoid writing","lose details","erase evidence"],"Dictation aids later writing.")
H("758.d.4.D",4,"A benefit of dictating notes at the scene is that:","details are captured while fresh",["details are lost","it replaces the report","it avoids documentation"],"Fresh memory is best.")
H("758.d.4.E",3,"One report is handwritten at the scene and another typed into a computer system. These demonstrate different ways to:","write a report",["avoid reports","delay reports","forget reports"],"Reports may be handwritten or computerized.")
H("758.d.4.E",4,"A computerized report system generally helps by:","storing and sharing reports efficiently",["deleting reports","preventing access","increasing errors"],"Digital systems aid sharing.")
H("758.d.5.A",3,"A judge throws out evidence that police found through an illegal search. This applies the:","exclusionary rule",["jury duty rule","traffic rule","tax rule"],"Illegally obtained evidence is excluded.")
H("758.d.5.A",4,"The exclusionary rule generally prevents prosecutors from using:","evidence obtained in violation of the Constitution",["any evidence at all","legally obtained evidence","witness names"],"Protects Fourth Amendment rights.")
H("758.d.5.B",3,"An officer wants to search a suspect's home with no emergency present. The officer typically must have a warrant or:","valid consent to search",["a hunch","a friend's note","a phone call"],"Searches require warrant or consent.")
H("758.d.5.B",4,"A search warrant must be based on:","probable cause and signed by a judge",["a rumor","a hunch","a request from a neighbor"],"Fourth Amendment requirement.")
H("758.d.5.C",3,"An officer who reasonably suspects a person is armed quickly pats down the outer clothing. This is governed by:","Terry v. Ohio",["Miranda v. Arizona","Brown v. Board","Marbury v. Madison"],"Terry allows limited frisks.")
H("758.d.5.C",4,"A Terry pat-down is limited to:","a search of outer clothing for weapons",["a full strip search","any container in a home","a car trunk search"],"Scope is limited to weapons.")
H("758.d.5.D",3,"After lawfully arresting a suspect, the officer searches the person and the area within immediate reach. This evaluates a:","search incident to arrest",["random search","trespass","private tour"],"It protects officers and preserves evidence.")
H("758.d.5.D",4,"A search incident to arrest is justified mainly to:","protect officers and prevent destruction of evidence",["collect gifts","delay the arrest","hide evidence"],"Safety and preservation.")
H("758.d.5.E",3,"Officers hear screams inside a home and enter without a warrant to help. This describes searching during:","emergency situations or other warrantless searches",["routine visits","vacations","parades"],"Exigent circumstances may allow entry.")
H("758.d.5.E",4,"Which situation may justify a warrantless entry?","an urgent threat to someone's life",["a neighbor's complaint about noise","curiosity","boredom"],"Exigency permits entry.")
H("758.d.5.F",3,"After an impound, the officer lists and documents the contents of the vehicle under department policy. This demonstrates how to conduct a:","vehicle inventory",["social visit","car show","test drive"],"Inventories protect property.")
H("758.d.5.F",4,"A vehicle inventory is performed mainly to:","protect the owner's property and the agency from claims",["search for secrets","avoid paperwork","delay towing"],"Administrative purpose.")
H("758.d.6.A",3,"A student studies the early case that allowed warrantless car searches because vehicles can be moved. This analyzes the precedent from:","Carroll v. United States",["Terry v. Ohio","Miranda v. Arizona","Mapp v. Ohio"],"Carroll created the automobile exception.")
H("758.d.6.A",4,"The automobile exception generally lets officers search a vehicle without a warrant when they have:","probable cause",["no reason","a hunch","a friend's request"],"Mobility plus probable cause.")
H("758.d.6.B",3,"Trainees divide a simulated scene into a grid and search each section methodically. This demonstrates a:","systematic search for physical evidence",["random glance","skipped search","casual walk"],"Grid, strip and spiral methods exist.")
H("758.d.6.B",4,"A search pattern that moves through a scene in parallel lines is the:","strip or line method",["random method","skip method","guess method"],"Strip search pattern.")
H("758.d.6.C",3,"Trainees practice searching a building, a vehicle, a suspect and a body with different safety rules. This demonstrates how to conduct:","building, vehicle, suspect and dead body searches",["picnic searches","library searches","web searches"],"Each requires distinct procedures.")
H("758.d.6.C",4,"A key rule when searching a suspect is to:","follow safety procedures and document what is found",["search carelessly","skip gloves","ignore officer safety"],"Safe, documented searches.")
H("758.d.6.D",3,"A K-9 handler walks a trained dog around a parked vehicle to detect narcotic odor. This explains how police canines are used to:","conduct legal searches",["entertain crowds","carry mail","guard livestock"],"Canines detect odors.")
H("758.d.6.D",4,"A trained police canine alerting to a vehicle may provide:","probable cause for a further search",["no useful information","a verdict","a sentence"],"A reliable alert can support probable cause.")
H("758.d.7.A",3,"A scene tech photographs and collects items, while a detective interviews witnesses and a prosecutor weighs charges. This compares the roles of:","crime scene investigators, detectives and prosecutors",["referees and coaches","chefs and servers","pilots and crew"],"Each role has distinct duties.")
H("758.d.7.A",4,"A crime scene investigator is mainly responsible for:","documenting and collecting physical evidence",["deciding guilt","sentencing","hiring jurors"],"CSIs process the scene.")
H("758.d.7.B",3,"One student photographs, another measures and another logs evidence during a mock scene exercise. This demonstrates the ability to:","work as a member of a team",["avoid cooperation","work alone","hide tasks"],"Scenes require teamwork.")
H("758.d.7.B",4,"Effective crime scene teams rely on:","clear roles and communication",["secrecy","random tasks","competition"],"Coordination prevents mistakes.")
H("758.d.7.C",3,"During a mock burglary scene, a trainee spots a footprint, a fiber and a discarded glove. This is the ability to:","discover and recognize evidence",["ignore evidence","destroy evidence","guess evidence"],"Observe carefully.")
H("758.d.7.C",4,"Before touching any evidence, an investigator should first:","document it where it is found",["pick it up","clean it","move it"],"Document in place.")
H("758.d.7.D",3,"A student applies the definition of burglary to decide what to search for and what to seize. This applies:","the elements of criminal law that guide search and seizure",["recipes","poems","schedules"],"Law guides what evidence matters.")
H("758.d.7.D",4,"Knowing the elements of an offense helps investigators:","identify evidence that proves each element",["avoid evidence","guess motives","skip photos"],"Evidence maps to elements.")
H("758.d.7.E",3,"Each person who handles an exhibit signs a log with date and time. This outlines the:","chain-of-custody procedure",["travel schedule","seating chart","menu"],"Chain of custody tracks handling.")
H("758.d.7.E",4,"Chain of custody is important because it:","shows evidence was handled and preserved properly",["makes evidence heavier","hides evidence","replaces testimony"],"Integrity is proven.")
H("758.d.7.F",3,"The tech photographs an item, bags it, seals it and initials the label. This demonstrates techniques for collecting, marking and:","packaging evidence",["trading evidence","losing evidence","discarding evidence"],"Proper packaging protects it.")
H("758.d.7.F",4,"Biological evidence like a damp cloth should generally be packaged in:","paper bags",["airtight plastic bags","glass jars sealed wet","aluminum foil"],"Paper lets moisture escape.")
H("758.d.7.G",3,"A tech uses video to walk through a scene and still photos for key items. This explains the use of:","video and still photography to present a scene",["radio broadcasts","paintings","songs"],"Both document the scene.")
H("758.d.7.G",4,"Video of a scene is helpful because it:","shows spatial relationships and layout",["replaces the report","removes evidence","alters the scene"],"Video gives context.")
H("758.d.7.H",3,"A prosecutor shows jurors an exhibit and a witness explains where it was found. This analyzes the use of:","evidence in a court of law",["costumes in a play","props in a movie","prizes in a game"],"Evidence supports arguments.")
H("758.d.7.H",4,"Evidence is more likely to be admitted if it is:","relevant and properly authenticated",["rumored","unlabeled","altered"],"Relevance and authentication.")
H("758.d.8.A",3,"A lab tech collects tiny paint chips, glass fragments and fibers from a hit-and-run scene. This demonstrates processing:","trace evidence",["bulk furniture","large vehicles","whole buildings"],"Trace evidence is small transferred material.")
H("758.d.8.A",4,"Trace evidence is best described as:","small materials transferred between people, objects or places",["large weapons","written notes","audio only"],"Locard's exchange principle.")
H("758.d.8.B",3,"An examiner compares a plaster cast from a scene with a suspect's sneaker sole. This identifies:","shoe and tire impressions",["finger length","voice tone","eye color"],"Impressions are compared for class and wear.")
H("758.d.8.B",4,"Wear patterns on a shoe sole can help link a shoe to an impression because they are:","unique to that shoe",["identical in all shoes","invisible","random every day"],"Individual characteristics.")
H("758.d.8.C",3,"Radial and concentric cracks in a broken window are examined to see which side was hit first. This determines the:","direction of a projectile through glass",["age of the glass","color of the glass","price of the glass"],"Fracture patterns show entry direction.")
H("758.d.8.C",4,"A projectile that passes through glass leaves a cone-shaped hole that is wider on the:","exit side",["entry side","top","bottom"],"The crater is wider on exit.")
H("758.d.8.D",3,"A forensic dentist examines a pattern of marks left in a victim's skin. This analyzes:","bite marks",["tool marks only","ink stains","paint chips"],"Odontology compares dentition.")
H("758.d.8.D",4,"Bite mark analysis compares the injury pattern with a suspect's:","teeth",["footwear","fingerprints","handwriting"],"Dental comparison.")
H("758.d.8.E",3,"Under a microscope, a hair shows a cuticle, cortex and medulla. This compares microscopic characteristics of:","human and animal hair",["glass and plastic","soil and sand","paper and cloth"],"Hair structure helps identification.")
H("758.d.8.E",4,"Which layer of a hair is the outermost scale layer?","cuticle",["medulla","cortex","root"],"The cuticle covers the hair.")
H("758.d.8.F",3,"A lab separates cotton and wool from nylon and polyester at a scene. This differentiates:","natural and synthetic fibers",["metals and plastics","liquids and gases","notes and tones"],"Fiber type aids comparison.")
H("758.d.8.F",4,"An example of a natural fiber is:","wool",["nylon","polyester","acrylic"],"Wool comes from animals.")
H("758.d.9.A",3,"Examiners sort prints into groups that curve up, loop back or spiral in circles. This compares the three major patterns of:","arches, loops and whorls",["squares, circles and lines","dots, dashes and blanks","bars, ridges and holes"],"The three basic fingerprint patterns.")
H("758.d.9.A",4,"The most common fingerprint pattern is the:","loop",["arch","whorl","delta only"],"Loops are most common.")
H("758.d.9.B",3,"An examiner marks places where a ridge splits in two or abruptly stops. These are fingerprint:","minutiae such as bifurcations and ridge endings",["colors","scars only","stains"],"Minutiae provide detail for comparison.")
H("758.d.9.B",4,"A ridge that divides into two branches is called a:","bifurcation",["whorl","arch","delta"],"Bifurcation is a split.")
H("758.d.9.C",3,"A bloody print, a print in soft wax and a print invisible to the eye are classified as:","patent, plastic and latent impressions",["red, blue and green","big, small and medium","hot, cold and warm"],"Types of fingerprint impressions.")
H("758.d.9.C",4,"A latent print is one that is:","not visible to the naked eye",["made in blood","pressed in clay","clearly visible"],"Latent = hidden.")
H("758.d.9.D",3,"A technician treats a paper note with a chemical that reacts with amino acids to reveal prints. This performs lifting on:","porous surfaces",["glass windows","smooth metal","plastic cups"],"Ninhydrin is used on porous items.")
H("758.d.9.D",4,"A chemical commonly used to develop latent prints on paper is:","ninhydrin",["powder only","water","sugar"],"Ninhydrin reacts with amino acids.")
H("758.d.9.E",3,"A technician dusts a glass window with powder and lifts the print with tape. This performs lifting on:","nonporous surfaces",["paper","cardboard","untreated wood"],"Powders work on smooth surfaces.")
H("758.d.9.E",4,"Fingerprint powder is typically applied with a:","soft brush",["spray gun","hammer","cloth only"],"Brush applies powder lightly.")
H("758.d.9.F",3,"A database compares an unknown print with millions on file to find possible matches. This explains the:","Automated Fingerprint Identification System (AFIS)",["telephone directory","library catalog","school roster"],"AFIS searches stored prints.")
H("758.d.9.F",4,"AFIS helps investigators by:","narrowing possible matches among stored fingerprints",["replacing all witnesses","creating prints","destroying records"],"Candidates are then verified by an examiner.")
H("758.d.9.G",3,"A trainee compares a latent lift from a scene with known inked prints from a suspect. This compares:","impression evidence collected at a simulated scene",["music samples","menu items","school records"],"Comparison links a suspect to a scene.")
H("758.d.9.G",4,"Fingerprint comparison relies on matching:","ridge details in the prints",["eye color","shoe size","height"],"Ridge detail is unique.")
H("758.d.10.A",3,"An analyst studies round versus elongated stains on a wall to estimate where the blood originated and the angle. This analyzes:","bloodstain patterns",["voice patterns","hair patterns","clothing patterns"],"Shape reveals angle and direction.")
H("758.d.10.A",4,"A more elongated bloodstain generally indicates the drop struck the surface at a:","lower angle",["higher angle","perfect right angle","vertical drop"],"Lower angles produce longer stains.")
H("758.d.10.B",3,"An investigator sprays a chemical that glows blue when it contacts traces of invisible blood. This explains the method of:","chemically identifying and locating hidden blood",["painting walls","cleaning floors","testing paper"],"Luminol reacts with blood.")
H("758.d.10.B",4,"A chemical commonly used to locate latent blood at a scene is:","luminol",["bleach","salt","sugar"],"Luminol produces chemiluminescence.")
H("758.d.11.A",3,"A student traces how alcohol is taken into the blood, carried through the body and removed by the liver. This analyzes alcohol's:","absorption, distribution and elimination",["color, taste and smell","cost, size and shape","brand, label and age"],"ADE explains BAC changes.")
H("758.d.11.A",4,"Most alcohol is eliminated from the body by the:","liver",["lungs only","skin only","bones"],"The liver metabolizes alcohol.")
H("758.d.11.B",3,"A lab analyst tests a blood sample for ethanol content using gas chromatography. This researches:","blood alcohol laboratory procedures",["tire repair","soil testing","paint mixing"],"BAC lab analysis.")
H("758.d.11.B",4,"Blood alcohol content is commonly measured and reported as:","a percentage of alcohol in the blood",["pounds of blood","hours since drinking","number of drinks only"],"BAC uses grams per 100 mL.")
H("758.d.11.C",3,"A heavy drinker may show fewer outward signs at the same blood level as a first-time drinker. This explains levels of:","tolerance and impairment due to alcohol",["hair length","height","clothing size"],"Tolerance masks outward signs.")
H("758.d.11.C",4,"Even with high tolerance, a driver with elevated BAC still has:","impaired reaction time and judgment",["perfect skills","no impairment","faster reflexes"],"Tolerance does not remove impairment.")
H("758.d.11.D",3,"A blood draw is stored in a gray-top tube, kept cool and labeled with a seal to avoid degradation. This explains precautions for:","proper preservation of blood samples",["throwing away samples","freezing without labels","leaving in a hot car"],"Preserve integrity.")
H("758.d.11.D",4,"Blood alcohol samples should be preserved by:","refrigerating them and sealing the container",["leaving them in sunlight","opening the tube","mixing with water"],"Prevents fermentation and tampering.")
H("758.d.12.A",3,"A lab tests a stain on a shirt to see whether it is blood and whether it is human. This explains crime lab procedures to determine if a stain is:","blood or another body fluid",["paint or ink only","oil only","juice only"],"Presumptive and confirmatory tests.")
H("758.d.12.A",4,"A presumptive test for blood is used to:","indicate whether a stain might be blood",["prove guilt","replace DNA","destroy the stain"],"Presumptive tests screen.")
H("758.d.12.B",3,"A lab researches ways to collect and analyze saliva, semen and other fluids found at a scene. These are methodologies for:","other body fluids",["car fluids","cooking oils","lawn chemicals"],"Different fluids need different tests.")
H("758.d.12.B",4,"DNA from body fluids is useful because it can:","link a person to the evidence",["replace testimony","change with age","vanish quickly"],"DNA is unique to individuals.")
H("758.d.13.A",3,"A chemist sorts drugs by medical use and abuse potential into Schedule I through V. This classifies substances under the:","Controlled Substances Act schedules",["Tax Code","Traffic Code","School Code"],"Schedules categorize drugs.")
H("758.d.13.A",4,"Substances placed in Schedule I are those with:","high abuse potential and no accepted medical use",["no abuse potential","only medical use","over-the-counter status"],"Schedule I is most restricted.")
H("758.d.13.B",3,"A forensic chemist uses color tests and instruments to name an unknown white powder. This identifies:","controlled substances",["cooking ingredients","cleaning products","paint colors"],"Lab tests identify drugs.")
H("758.d.13.B",4,"A confirmatory lab method often used to identify drugs is:","gas chromatography–mass spectrometry",["a coin flip","a visual guess","a taste test"],"GC-MS confirms identity.")
H("758.d.14.A",3,"An examiner compares scratches left by a screwdriver on a door frame with a suspect's tool. This explains individual characteristics of:","tool marks",["handwriting","voice","gait"],"Tools leave unique marks.")
H("758.d.14.A",4,"A tool mark's individual characteristics come from:","random wear and damage on the tool",["the brand label","the color of the tool","the store it came from"],"Wear makes marks unique.")
H("758.d.14.B",3,"A firearms examiner explains how pulling the trigger releases the hammer, strikes the primer and fires the round. This describes the:","mechanism of modern firearms",["recipe of a meal","path of a river","motion of a planet"],"Firing sequence.")
H("758.d.14.B",4,"In a firearm, the primer is struck by the:","firing pin",["barrel","magazine","sight"],"The firing pin ignites the primer.")
H("758.d.14.C",3,"Rifling grooves leave marks on a bullet and the breech leaves marks on a casing. This recognizes characteristics of:","bullet and cartridge cases",["paper and ink","tires and rims","glass and wood"],"Marks link ammunition to a weapon.")
H("758.d.14.C",4,"Spiral grooves inside a barrel that make a bullet spin are called:","rifling",["tapering","sighting","chambering"],"Rifling stabilizes a bullet.")
H("758.d.14.D",3,"A lab swabs a suspect's hands and tests for barium, lead and antimony particles. This describes analysis for:","gunshot residue",["fingerprints","hair color","fibers"],"GSR indicates firearm discharge.")
H("758.d.14.D",4,"Gunshot residue samples are typically collected from a suspect's:","hands",["shoes only","hair only","teeth"],"Hands are swabbed.")
H("758.d.14.E",3,"Cartridge casings from different scenes are imaged and searched in a national network to find links. This recognizes the information in the:","National Integrated Ballistic Information Network (NIBIN)",["school directory","library network","weather network"],"NIBIN links firearm crimes.")
H("758.d.14.E",4,"NIBIN helps investigators by:","linking ballistic evidence from different crimes",["selling firearms","testing alcohol","printing reports"],"Connects cases.")
H("758.d.15.A",3,"A medical examiner notes that a body has stiffened and calculates how long ago death likely occurred. This explains the process and timeline of:","rigor mortis",["lividity only","aging","hair growth"],"Rigor peaks and then fades.")
H("758.d.15.A",4,"Rigor mortis is the stiffening of muscles that begins:","a few hours after death",["immediately before death","after one week","months later"],"Onset in hours.")
H("758.d.15.B",3,"Blood settles in the lowest parts of the body and creates purple discoloration. This explains:","post mortem lividity",["rigor","bruising from a fall","a rash"],"Livor mortis indicates body position.")
H("758.d.15.B",4,"Lividity can help investigators determine whether a body was:","moved after death",["fed recently","drinking alcohol","exercising"],"Fixed lividity shows position.")
H("758.d.15.C",3,"An entomologist studies the insects and their life stages on a body to estimate time since death. This determines time of death using:","entomology",["geology","astronomy","botany"],"Insect development is a clock.")
H("758.d.15.C",4,"Forensic entomology often relies on the development stages of:","blowfly larvae",["bees","butterflies","ants only"],"Blowflies colonize quickly.")
H("758.d.15.D",3,"Students review old cases to see which methods were used to estimate time and cause of death. This uses:","case studies",["horoscopes","fiction","rumors"],"Cases show applied methods.")
H("758.d.15.D",4,"Determining cause of death in an investigation is typically the role of a:","medical examiner or coroner",["jury","bailiff","clerk"],"Medical examiners determine cause.")
H("758.d.16.A",3,"A report labels the person harmed as the victim, the person who calls police as the complainant, a person with knowledge as a witness and the accused as a suspect. This explains the terms as they apply to:","an investigation",["a recipe","a school","a market"],"Roles in a case.")
H("758.d.16.A",4,"A person who saw or heard events relevant to a crime is a:","witness",["suspect","juror","bailiff"],"Witnesses provide information.")
H("758.d.16.B",3,"An investigator talks with a witness to gather information and later questions a suspect to seek admissions. This demonstrates:","interviewing and interrogating during an investigation",["debating a rule","teaching a class","playing a game"],"Interviews gather info; interrogations seek confessions.")
H("758.d.16.B",4,"An interview differs from an interrogation because it is:","non-accusatory and aimed at gathering information",["always secret","always recorded","always aggressive"],"Interviews are information gathering.")
H("758.d.16.C",3,"An investigator uses open-ended questions, active listening and a calm tone to build rapport. This demonstrates:","effective questioning and positive communication",["intimidation","interruption","distraction"],"Rapport yields better information.")
H("758.d.16.C",4,"An open-ended question typically begins with:","'Tell me about...'",["'Did you...'","'Isn't it true...'","'Yes or no?'"],"Open questions invite narrative.")
H("758.d.16.D",3,"Officers inform a suspect in custody of the right to remain silent and to an attorney before questioning. This analyzes the importance of:","reading the Miranda warnings",["a school bell","a ballgame","a coupon"],"Miranda protects Fifth Amendment rights.")
H("758.d.16.D",4,"Miranda warnings are required before:","custodial interrogation",["any conversation","a traffic stop","a photograph"],"Custody plus interrogation.")
H("758.d.16.E",3,"Investigators use simple words, a comfortable setting and often a trained specialist when speaking with a young witness. This describes techniques to interview:","children and juveniles",["adult executives","retired officers","teachers"],"Child interviews require care.")
H("758.d.16.E",4,"When interviewing a child, an investigator should avoid:","leading or suggestive questions",["simple language","patience","a quiet setting"],"Leading questions distort accounts.")
H("758.d.17.A",3,"A detective gathers statements from victims and witnesses to create a description of the suspect. This compiles:","information provided by victims and witnesses",["recipes","maps only","weather"],"Descriptions come from witnesses.")
H("758.d.17.A",4,"Descriptions of a suspect from different witnesses should be:","compared for consistency and corroborated",["thrown out","combined without review","kept secret"],"Corroboration improves reliability.")
H("758.d.17.B",3,"Footprints, fibers and tool marks at a scene are examined to infer who was there. This examines evidence to determine a:","suspect's characteristics or identity",["witness's age","jury's size","weather forecast"],"Evidence points to a suspect.")
H("758.d.17.B",4,"Physical evidence from a scene can help establish:","who was present and what occurred",["nothing useful","only the time of day","only the weather"],"Evidence reconstructs events.")
H("758.d.17.C",3,"Detectives notice that a burglar always enters through a rear window and takes only jewelry. This identifies the suspect's:","modus operandi",["birth date","hair color","class schedule"],"MO is a repeated method.")
H("758.d.17.C",4,"A suspect's modus operandi is:","a characteristic way of committing crimes",["a signature tattoo","a mailing address","a school grade"],"MO is method of operation.")
H("758.d.17.D",3,"A witness picks eyes, nose and hairstyle from a computer program to build a face of a suspect. This analyzes:","computerized composite sketch applications",["photo editing for fun","video games","music software"],"Identi-Kit builds composites.")
H("758.d.17.D",4,"A composite sketch helps investigators by:","creating a visual likeness from a witness's description",["proving guilt","replacing evidence","naming the suspect automatically"],"Composites generate leads.")
H("758.d.17.E",3,"A witness views six similar photos shown one at a time to decide whether the suspect is among them. This describes techniques for photo lineups and:","identification procedures",["menu orders","bus schedules","tax forms"],"Lineups must be fair.")
H("758.d.17.E",4,"To keep a photo lineup fair, the suspect's photo should be placed with others that:","resemble the witness's description",["look very different","are all identical","are cartoon images"],"Fillers must be similar.")
H("758.d.17.F",3,"An agency researches body cameras, wiretaps and cell-site records as tools for observation and capture of communications. This researches:","audio, video and electronic surveillance",["cooking shows","board games","radio dramas"],"Surveillance tools gather evidence.")
H("758.d.17.F",4,"Electronic surveillance such as wiretapping generally requires:","a court order based on probable cause",["no permission","a hunch","a friend's text"],"Fourth Amendment and statutes apply.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_101.jsonl"))
